package com.trainflow.program; import jakarta.persistence.*; import java.time.Instant; import java.util.*; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="training_program_days") public class TrainingProgramDay{@Id @JdbcTypeCode(SqlTypes.VARCHAR)@Column(columnDefinition="char(36)")private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="training_program_id")private TrainingProgram program;@Column(nullable=false,length=250)private String title;@Column(nullable=false)private int position;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@OneToMany(mappedBy="day",cascade=CascadeType.ALL,orphanRemoval=true)@OrderBy("position asc")private List<TrainingProgramItem> items=new ArrayList<>();protected TrainingProgramDay(){}public TrainingProgramDay(TrainingProgram p,String t,int pos){id=UUID.randomUUID();program=p;title=t;position=pos;}@PrePersist void insert(){var n=Instant.now();if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}public UUID getId(){return id;}public TrainingProgram getProgram(){return program;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public int getPosition(){return position;}public void setPosition(int v){position=v;}public List<TrainingProgramItem> getItems(){return items;}}
